#!/usr/bin/env bash
# =============================================================================
# HERCOSSNUX PQC IP Core - Layer 3B step 5: ML-DSA-65 Sign sequencer
#
# Nine vectors, byte for byte, with the final kappa checked before the bytes:
# the eight ACVP cases plus one CONSTRUCTED case whose iteration 10 has hint
# weight exactly OMEGA+1 = 56. The ACVP vectors never reach the hint-weight
# rejection at all (branch coverage: z=11 r0=16 ct0=0 h=0), so without that
# case the bound is live but constrained by nothing, and the mutation that
# relaxes it survives. This closes Layer 3B: NTT-D, samplers, rounding, codecs and now the
# Sign sequencer.
#
# RUNTIME WARNING. The eight vectors run 35 rejection-loop iterations between
# them and each iteration regenerates the whole K x L matrix, 30 SampleNTT
# calls. Expect tens of minutes. The four checkpoints run first and are fast,
# so a failure in the early stages surfaces within a minute or two.
#
# FIXED FROM THE FIRST DELIVERY: the testbench now calls std.env.finish after
# its final report. The first version relied on --stop-time, so GHDL kept
# simulating dead time after the result was computed, and because the output
# goes through a pipe nothing was flushed until the process died: the run
# looked hung for minutes per checkpoint and for hours on the full run, with
# the answer already printed into a stuck buffer. The stop-times remain only
# as safety bounds; every stage now exits at its report.
#
# THE MESSAGE IS NOT STORED. mu is a 64-byte input; the ACVP messages reach
# 7583 bytes and a message may be arbitrarily long, so a fixed buffer would be
# a limit invented by the implementation. Verified against the model that mu
# is the only message-derived value any later step needs.
#
# THE DEFECT THE CHECKPOINTS COULD NOT SEE. Every checkpoint passed while the
# full run still disagreed with ACVP, with small deltas appearing at iteration
# 1 and never before. The cause was in the sampler: sgn is OR-ed in and was
# cleared only on reset, so the first SampleInBall of a run was always clean
# and every later one accumulated the previous call's sign bits. The sampler
# testbench could not have caught it, because it asserts reset between
# vectors, which clears sgn and makes the two behaviours identical. It now
# runs the SampleInBall cases back to back, and that version fails on the
# unfixed RTL with a flipped sign.
#
# This step also REPLACES sampler_d, codec_d, poly_mem_d and two testbenches:
# the polynomial memory widened to 47 slots, the codec gained unpack modes for
# s and t0 and a 14-bit byte address, and the sampler clears sgn per call. All
# earlier signatures are re-run below and are unchanged.
#
# Installs into: $HOME/vhdl_repo/IP_Cores/PQC/
# Expected final line:
#   PQC L3B DSASIGN PASS vectors=9 sig=cef491e2e25e7f39
# =============================================================================
set -u
(
  set -e
  DEST="$HOME/vhdl_repo/IP_Cores/PQC"
  mkdir -p "$DEST/rtl" "$DEST/verif" "$DEST/doc"
  for f in rtl/ntt_d_unit.vhd rtl/pqc_round_d_pkg.vhd rtl/keccak_sponge.vhd; do
    if [ ! -f "$DEST/$f" ]; then
      echo "MISSING PREREQUISITE: $f"
      exit 1
    fi
  done
  base64 -d > "$DEST/rtl/dsa_sign.vhd" << 'B64EOF'
LS0gPT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09
PT09PT09PT09PT09PT09PT09PT09PT0KLS0gSEVSQ09TU05VWCBQUUMgSVAgQ29yZSAtIExheWVy
