B64EOF
  chmod +x "$DEST/verif/mutate_dsasign.sh"
  cd "$DEST/verif"
  rm -rf work-obj08.cf
  ghdl -a --std=08 ../rtl/keccak_pkg.vhd ../rtl/keccak_f1600.vhd \
       ../rtl/keccak_sponge.vhd ../rtl/ntt_d_tables_pkg.vhd \
       ../rtl/pqc_round_d_pkg.vhd ../rtl/poly_mem_d.vhd \
       ../rtl/byte_mem_d.vhd ../rtl/ntt_d_unit.vhd ../rtl/sampler_d.vhd \
       ../rtl/codec_d.vhd ../rtl/dsa_sign.vhd ../rtl/dsa_sign_top.vhd \
       tb_ntt_d.vhd tb_sampler_d.vhd tb_round_d.vhd tb_codec_d.vhd \
       tb_dsa_sign.vhd

  echo "--- Layer 3B primitives still bit-identical ---"
  for t in tb_ntt_d tb_sampler_d tb_round_d tb_codec_d; do
    ghdl -e --std=08 $t > /dev/null 2>&1
  done
  ghdl -r --std=08 tb_ntt_d --stop-time=300ms 2>&1 \
    | grep "NTTD PASS" | sed 's/.*(report note): //'
  ghdl -r --std=08 tb_sampler_d --stop-time=100ms 2>&1 \
    | grep "SAMPD PASS" | sed 's/.*(report note): //'
  ghdl -r --std=08 tb_round_d --stop-time=50ms 2>&1 \
    | grep "ROUNDD PASS" | sed 's/.*(report note): //'
  ghdl -r --std=08 tb_codec_d --stop-time=300ms 2>&1 \
    | grep "CODECD PASS" | sed 's/.*(report note): //'

  ghdl -e --std=08 tb_dsa_sign > /dev/null 2>&1
  echo "--- Sign checkpoints, first iteration (about a minute each) ---"
  for st in 1 2 3 4; do
    echo "  checkpoint SP$st running..."
    ghdl -r --std=08 tb_dsa_sign -gG_STAGE=$st --stop-time=8000ms 2>&1 \
      | grep "CHECKPOINT PASS" | sed 's/.*(report note): //'
  done

  echo "--- Sign, nine vectors: 51 rejection-loop iterations, ---"
  echo "--- expect tens of minutes with no output until the PASS line ---"
  ghdl -r --std=08 tb_dsa_sign -gG_STAGE=0 --stop-time=400000ms 2>&1 \
    | grep "DSASIGN PASS" | sed 's/.*(report note): //'
)
